142	            ),
143	            (100, Source::Default)
144	        );
145	    }
146	
147	    #[test]
148	    fn a_source_restating_the_default_is_marked() {
149	        let file = Source::File(PathBuf::from("iiac-perf.md"));
150	        let same = Param::new("blocks", "100".to_string(), "100", file.clone());
151	        assert_eq!(source_cell(&same), "(iiac-perf.md, same as default)");
152	        let differs = Param::new("blocks", "50".to_string(), "100", file);
153	        assert_eq!(source_cell(&differs), "(iiac-perf.md)");
